  "new": "SELECT country AS \"Country\", ROUND(total_twh,0) AS \"Total TWh\", ROUND(coal_twh,0) AS \"Coal\", ROUND(gas_twh,0) AS \"Gas\", ROUND(nuclear_twh,0) AS \"Nuclear\", ROUND(hydro_twh,0) AS \"Hydro\", ROUND(solar_twh,0) AS \"Solar\", ROUND(wind_twh,0) AS \"Wind\", renewables_share_pct AS \"Renewables %\", per_capita_kwh AS \"kWh/Capita\" FROM global_electricity WHERE year = 2023 AND country <> 'World' ORDER BY \"Total TWh\" DESC"
